+func writeBodyChunked(w *bufio.Writer, r io.Reader) error {
+    // Use a stack‑allocated buffer to avoid sync.Pool contention.
+    // 32 KiB provides a good balance between syscall count and stack usage.
+    var buf [32 * 1024]byte
+    slice := buf[:]
+
+    var err error
+    var n int
+    for {
+        n, err = r.Read(slice)
+        if n == 0 {
+            if err == nil {
+                continue
+            }
+            if err == io.EOF {
+                // Write the final zero‑length chunk.
+                if err = writeChunk(w, slice[:0]); err != nil {
+                    break
+                }
+                err = nil
+            }
+            break
+        }
+        if err = writeChunk(w, slice[:n]); err != nil {
+            break
+        }
+    }
+    return err
+}

