+func copyZeroAlloc(w io.Writer, r io.Reader) (int64, error) {
+	// Fast path for copying from *os.File to *strings.Builder.
+	// This avoids the default os.File.WriteTo implementation which
+	// allocates a new buffer on each call.
+	if f, ok := r.(*os.File); ok {
+		if sb, ok := w.(*strings.Builder); ok {
+			if fi, err := f.Stat(); err == nil && fi.Size() > 0 {
+				// Pre‑grow the builder to the expected size.
+				sb.Grow(int(fi.Size()))
+			}
+			// Use a pooled buffer for the copy loop.
+			buf := copyBufPool.Get().([]byte)
+			var total int64
+			for {
+				n, err := f.Read(buf)
+				if n > 0 {
+					if _, werr := sb.Write(buf[:n]); werr != nil {
+						copyBufPool.Put(buf)
+						return total + int64(n), werr
+					}
+					total += int64(n)
+				}
+				if err == io.EOF {
+					copyBufPool.Put(buf)
+					return total, nil
+				}
+				if err != nil {
+					copyBufPool.Put(buf)
+					return total, err
+				}
+			}
+		}
