+// fastHexDecode converts two hex characters (high and low) to a byte.
+// It returns the decoded byte and a bool indicating whether the conversion succeeded.
+func fastHexDecode(high, low byte) (byte, bool) {
+	// Convert high nibble.
+	var hb, lb byte
+	switch {
+	case '0' <= high && high <= '9':
+		hb = high - '0'
+	case 'a' <= high && high <= 'f':
+		hb = high - 'a' + 10
+	case 'A' <= high && high <= 'F':
+		hb = high - 'A' + 10
+	default:
+		return 0, false
+	}
+	// Convert low nibble.
+	switch {
+	case '0' <= low && low <= '9':
+		lb = low - '0'
+	case 'a' <= low && low <= 'f':
+		lb = low - 'a' + 10
+	case 'A' <= low && low <= 'F':
+		lb = low - 'A' + 10
+	default:
+		return 0, false
+	}
+	return hb<<4 | lb, true
