+func ensureCap(buf []byte, need int) []byte {
+	if cap(buf)-len(buf) < need {
+		// Grow to at least len+need, letting rt.GrowSlice handle rounding.
+		buf = rt.GrowSlice(typeByte, buf, len(buf)+need)
